/**
 * Platform layer (principle VI): the only access point to `browser.i18n`.
 * No other logic here; key typing and formatting live in src/ui/i18n.ts.
 */
import { browser } from 'wxt/browser';

/**
 * Catalog message. The dotted key (`popup.summary.addButton`) becomes the message name
 * `popup_summary_addButton` generated by @wxt-dev/i18n in `_locales/<language>/messages.json`.
 */
export function getMessage(key: string, substitutions?: string | string[]): string {
  // The browser.i18n types only accept predefined messages (`@@ui_locale`…):
  // catalog keys are typed upstream by `MessageKey` (src/ui/i18n.ts).
  const name = key.replaceAll('.', '_') as Parameters<typeof browser.i18n.getMessage>[0];
  return browser.i18n.getMessage(name, substitutions);
}

export function getUILanguage(): string {
  return browser.i18n.getUILanguage();
}
